package com.pathways.rules.content

import com.pathways.model.DiceExpr
import kotlinx.serialization.json.Json

/**
 * Loads the committed content files (under /content/ on the classpath,
 * e.g. /content/skills.json), generated by tools/extract_content.py from
 * the rulebook and the fixture spreadsheets, into typed lists. Each file
 * is parsed at most once per process, via [lazy].
 */
object ContentLoader {

    private val json = Json { ignoreUnknownKeys = true }

    private val skillsLazy: List<SkillDefinition> by lazy { load("skills.json") }
    private val advantagesLazy: List<TraitDefinition> by lazy { load("advantages.json") }
    private val disadvantagesLazy: List<TraitDefinition> by lazy { load("disadvantages.json") }
    private val pathwaysLazy: List<SequenceBlock> by lazy { load("pathways.json") }
    private val actingMethodLazy: List<ActingQuality> by lazy { load("acting_method.json") }
    private val potionConsumptionLazy: List<PcrRow> by lazy { load("potion_consumption.json") }
    private val corGainedLazy: List<CorGain> by lazy { load("cor_gained.json") }
    private val poolThresholdsLazy: List<PoolThreshold> by lazy { load("pool_thresholds.json") }
    private val ritualWeightsLazy: List<RitualWeight> by lazy { load("ritual_weights.json") }
    private val ritualFailuresLazy: List<RitualFailure> by lazy { load("ritual_failures.json") }
    private val ritualCriticalsLazy: List<RitualCritical> by lazy {
        load<RitualCritical>("ritual_critical.json").sortedBy { it.low }
    }
    private val unarmedAttacksLazy: List<UnarmedAttack> by lazy { load("unarmed_attacks.json") }
    private val rangePenaltiesLazy: List<RangePenalty> by lazy {
        // Sorted so a distance lookup walks the bands nearest-first whatever
        // order the file lists them in -- which is also what settles the
        // book's own overlap at 100 metres. See Ranged.penaltyFor.
        load<RangePenalty>("range_penalties.json").sortedBy { it.from }
    }
    private val rangedModifiersLazy: List<RangedModifier> by lazy { load("ranged_modifiers.json") }
    private val hitLocationsLazy: List<HitLocation> by lazy { load("hit_locations.json") }
    private val woundingMultipliersLazy: List<WoundingMultiplier> by lazy {
        load("wounding_multipliers.json")
    }
    private val maneuversLazy: List<Maneuver> by lazy { load("maneuvers.json") }
    private val extraEffortLazy: List<ExtraEffort> by lazy { load("extra_effort.json") }
    private val attackOptionsLazy: List<AttackOption> by lazy { load("attack_options.json") }
    private val defensesLazy: List<Defense> by lazy { load("defenses.json") }
    private val defenseModifiersLazy: List<DefenseModifier> by lazy { load("defense_modifiers.json") }
    private val frightTriggersLazy: List<FrightTrigger> by lazy { load("fright_triggers.json") }
    private val frightEffectsLazy: List<FrightEffect> by lazy {
        // Sorted so a band lookup can walk the table in the order the book
        // prints it whatever order the file happens to list.
        load<FrightEffect>("fright_effects.json").sortedBy { it.low }
    }
    private val ritualCorThresholdsLazy: List<RitualCorThreshold> by lazy {
        // Sorted here so every caller sees the ladder in ascending order
        // whatever order the file happens to list it in.
        load<RitualCorThreshold>("ritual_cor_thresholds.json").sortedBy { it.cor }
    }
    private val thrustSwingLazy: Map<Int, DamageRow> by lazy {
        val rows = load<DamageRowJson>("thrust_swing.json")
        // Same defect class as Character's duplicate-PurchasedSkill guard:
        // associate() silently keeps only the last row for a repeated key and
        // drops the rest, so two rows sharing an ST would quietly lose one
        // instead of failing loudly. There are none in the committed content
        // today, but this is cheap insurance against a future edit reintroducing
        // one.
        val duplicates = rows.groupBy { it.st }.filterValues { it.size > 1 }.keys
        require(duplicates.isEmpty()) {
            "thrust_swing.json has duplicate ST row(s): ${duplicates.sorted()} -- " +
                "associate() would silently keep only the last and drop the rest"
        }
        rows.associate { it.st to DamageRow(it.st, DiceExpr.parse(it.thrust), DiceExpr.parse(it.swing)) }
    }

    fun skills(): List<SkillDefinition> = skillsLazy
    fun advantages(): List<TraitDefinition> = advantagesLazy
    fun disadvantages(): List<TraitDefinition> = disadvantagesLazy
    fun thrustSwing(): Map<Int, DamageRow> = thrustSwingLazy

    /** The 88 Sequence stat blocks (22 pathways x Sequences 9/8/7/6). */
    fun pathways(): List<SequenceBlock> = pathwaysLazy

    /** Digestion gain per session, by how well the role was acted (Ch. 6). */
    fun actingMethod(): List<ActingQuality> = actingMethodLazy

    /** The Potion Consumption Roll table, by digestion percentage (Ch. 6). */
    fun potionConsumption(): List<PcrRow> = potionConsumptionLazy

    /** What each listed action costs in corruption (Ch. 6, p. 45). */
    fun corGained(): List<CorGain> = corGainedLazy

    /**
     * The HP and SPI threshold ladders (Ch. 5), in the order the book prints
     * them -- worst last. FP has no rows; see [PoolThreshold].
     */
    fun poolThresholds(): List<PoolThreshold> = poolThresholdsLazy

    /** The Range Penalties bands (Ch. 5, p. 39), ascending by distance. */
    fun rangePenalties(): List<RangePenalty> = rangePenaltiesLazy

    /** Other Ranged Modifiers: movement, cover, darkness, Aim (Ch. 5). */
    fun rangedModifiers(): List<RangedModifier> = rangedModifiersLazy

    /** The Optional Hit Locations table (Ch. 5, p. 41), in printed order. */
    fun hitLocations(): List<HitLocation> = hitLocationsLazy

    /** The Optional Wounding Multipliers table (Ch. 5, p. 41). */
    fun woundingMultipliers(): List<WoundingMultiplier> = woundingMultipliersLazy

    /** The Brawling and Boxing attack tables (Ch. 5, p. 38-39). */
    fun unarmedAttacks(): List<UnarmedAttack> = unarmedAttacksLazy

    /** The one-per-turn Maneuvers table (Ch. 5, p. 36), in printed order. */
    fun maneuvers(): List<Maneuver> = maneuversLazy

    /** The Extra Effort bullets under it: free actions bought with FP. */
    fun extraEffort(): List<ExtraEffort> = extraEffortLazy

    /** Rapid Strike and Deceptive Attack, as prose (Ch. 5, p. 36-37). */
    fun attackOptions(): List<AttackOption> = attackOptionsLazy

    /** The Active Defenses table as the book prints it (Ch. 5, p. 36-37). */
    fun defenses(): List<Defense> = defensesLazy

    /** The bullets under that table: facing, Retreat, Acrobatic Dodge, Dive. */
    fun defenseModifiers(): List<DefenseModifier> = defenseModifiersLazy

    /** How hard each category of ritual is to cast (Ch. 7, p. 67). */
    fun ritualWeights(): List<RitualWeight> = ritualWeightsLazy

    /** What a failed ritual costs, by margin (Ch. 7, p. 67). */
    fun ritualFailures(): List<RitualFailure> = ritualFailuresLazy

    /** The Critical Failure Table, ascending by band (Ch. 7, p. 67-68). */
    fun ritualCriticals(): List<RitualCritical> = ritualCriticalsLazy

    /** What each kind of supernatural sight does to a Fright Check (Ch. 5). */
    fun frightTriggers(): List<FrightTrigger> = frightTriggersLazy

    /** The Fright / Awe / Confusion effects table, ascending by band (Ch. 5). */
    fun frightEffects(): List<FrightEffect> = frightEffectsLazy

    /**
     * The 3/5/8/10 corruption ladder printed under "Corruption from Ritual
     * Work" (Ch. 7, p. 68), ascending. Ritual-scoped, not general: see
     * [RitualCorThreshold].
     */
    fun ritualCorThresholds(): List<RitualCorThreshold> = ritualCorThresholdsLazy

    private inline fun <reified T> load(resource: String): List<T> {
        val stream = ContentLoader::class.java.getResourceAsStream("/content/$resource")
            ?: error("content file not found on classpath: $resource")
        val text = stream.bufferedReader().use { it.readText() }
        return json.decodeFromString<ContentFile<T>>(text).entries
    }
}
